mapper.data:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "user",
      "content": "Write a friendly 3-paragraph email to {{4.client_name}} who has been using AI chat automation for {{4.days_active}} days on the Starter plan at $197/mo. Mention their results are great and suggest upgrading to Growth at $397/mo which adds weekly digest, lead scoring, and client health monitoring. Be genuine and never pushy. Return only the email body."
    }
  ],
  "max_tokens": 500,
  "temperature": 0.7
}

{
  "from": "Brian at {{4.client_name}} <{{env.RESEND_FROM_ADDRESS}}>",
  "to": ["{{4.client_email}}"],
  "subject": "You have outgrown Starter — here is what is next",
  "text": "{{6.data.choices[0].message.content}}"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "Upsell email sent to {{4.client_name}} — {{4.days_active}} days active on Starter",
  "html": "<h2 style='color:#16a34a;'>Upsell Opportunity Alert</h2><p>An upgrade email was just sent to a Starter client who has been live for {{4.days_active}} days.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Client</td><td style='padding:6px 12px;'>{{4.client_name}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Email</td><td style='padding:6px 12px;'>{{4.client_email}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Current Plan</td><td style='padding:6px 12px;'>Starter — $197/mo</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Days Active</td><td style='padding:6px 12px;'>{{4.days_active}} days (since {{4.go_live_date}})</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Upgrade Target</td><td style='padding:6px 12px;'>Growth — $397/mo</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Email Sent</td><td style='padding:6px 12px;'>{{4.run_date}} at 11:00 AM ET</td></tr></table><p>Follow up if you do not hear back within 5 business days.</p>"
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ERROR] Scenario R Upsell Campaign Failed — {{4.client_name}}",
  "html": "<h2 style='color:#dc2626;'>Scenario R Error</h2><p>The Starter-to-Growth Upsell Campaign (Scenario R) encountered an error and did not complete successfully for one or more clients.</p><table style='border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;'><tr><td style='padding:6px 12px;font-weight:bold;'>Error Message</td><td style='padding:6px 12px;'>{{error.message}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Failed Module</td><td style='padding:6px 12px;'>{{error.module}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Time</td><td style='padding:6px 12px;'>{{formatDate(now; 'MMMM D, YYYY h:mm A'; 'America/New_York')}} ET</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Client Name</td><td style='padding:6px 12px;'>{{4.client_name}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Client Email</td><td style='padding:6px 12px;'>{{4.client_email}}</td></tr><tr style='background:#f3f4f6;'><td style='padding:6px 12px;font-weight:bold;'>Days Active</td><td style='padding:6px 12px;'>{{4.days_active}}</td></tr><tr><td style='padding:6px 12px;font-weight:bold;'>Go-Live Date</td><td style='padding:6px 12px;'>{{4.go_live_date}}</td></tr></table><p>Please check the Make.com execution log and send the upsell email to this client manually if needed.</p>"
}
